import{_ as a,c as i,o as r,ah as l}from"./chunks/framework.BssxmkiH.js";const p=JSON.parse('{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md"}'),o={name:"changelog.md"};function n(t,e,d,s,h,c){return r(),i("div",null,e[0]||(e[0]=[l('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to “Changelog”">​</a></h1><h2 id="version-2-0-0" tabindex="-1">Version 2.0.0 <a class="header-anchor" href="#version-2-0-0" aria-label="Permalink to “Version 2.0.0”">​</a></h2><p>Initial Release</p><h2 id="version-2-0-1" tabindex="-1">Version 2.0.1 <a class="header-anchor" href="#version-2-0-1" aria-label="Permalink to “Version 2.0.1”">​</a></h2><h3 id="new" tabindex="-1">NEW <a class="header-anchor" href="#new" aria-label="Permalink to “NEW”">​</a></h3><ul><li>Added silver lining effect.</li></ul><h3 id="fixed" tabindex="-1">FIXED <a class="header-anchor" href="#fixed" aria-label="Permalink to “FIXED”">​</a></h3><ul><li>Potential vunerabilities causing crashed on some platforms</li></ul><h3 id="improvement" tabindex="-1">IMPROVEMENT <a class="header-anchor" href="#improvement" aria-label="Permalink to “IMPROVEMENT”">​</a></h3><ul><li>Curvature property no longer causes stretching artifacts at values &gt; 0.5 when 3DSampling is disabled, thus 3DSampling is removed. (Minor breaking change)</li></ul><h2 id="version-2-1-0" tabindex="-1">Version 2.1.0 <a class="header-anchor" href="#version-2-1-0" aria-label="Permalink to “Version 2.1.0”">​</a></h2><h3 id="new-1" tabindex="-1">NEW <a class="header-anchor" href="#new-1" aria-label="Permalink to “NEW”">​</a></h3><ul><li>Compatability support for Unity 2022.3+.</li><li>Added stratocumulus cloud type.</li><li>Added perlin detail type.</li><li>Removed <code>AbsorptionSpread</code> property.</li><li>Added <a href="./cloud-settings"><code>AbsorptionLimit</code></a> property.</li></ul><h3 id="improvement-1" tabindex="-1">IMPROVEMENT <a class="header-anchor" href="#improvement-1" aria-label="Permalink to “IMPROVEMENT”">​</a></h3><ul><li>Added the option to disable camera background type warning.</li></ul><h2 id="version-2-6-0" tabindex="-1">Version 2.6.0 <a class="header-anchor" href="#version-2-6-0" aria-label="Permalink to “Version 2.6.0”">​</a></h2><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>VERSION 2.6.0 HAD A MAJOR PROJECT STRUCTURE CHANGE. ENSURE TO DELETE OLD PACKAGE FILES BEFORE IMPORTING THIS ONE.</p></div><h3 id="new-2" tabindex="-1">NEW <a class="header-anchor" href="#new-2" aria-label="Permalink to “NEW”">​</a></h3><ul><li>Added VR Support</li><li>Added support for Built-in Render Pipeline</li><li>Added astronomical positioning mode for celestial bodies (moon and sun) based on a specified time of day / time of year using earth&#39;s orbital model.</li><li>Added skymap rotation.</li><li>Added earth curvature, simulating the look of observing from an elevated height, giving the earth a curved look.</li><li>Added atmospheric height fog (aerial perspective).</li></ul><h3 id="improvements" tabindex="-1">IMPROVEMENTS <a class="header-anchor" href="#improvements" aria-label="Permalink to “IMPROVEMENTS”">​</a></h3><ul><li>Cloud shadow tiling.</li><li>Enhanced moon rendering</li></ul><h3 id="fixed-1" tabindex="-1">FIXED <a class="header-anchor" href="#fixed-1" aria-label="Permalink to “FIXED”">​</a></h3><ul><li>Fixed shader compilation error on some platforms</li><li>Fixed errors on newer versions of Unity and extended compatability support to range from Unity 2021.3 to Unity 6.5</li><li>Fixed moon varying brightness, inconsistent rotation and shaping issues.</li><li>Fixed errors while loading presets on Unity 2021.3 - Unity 2022.3</li><li>Fixed other bugs</li></ul>',23)]))}const u=a(o,[["render",n]]);export{p as __pageData,u as default};
